PATH_TO_POSTPROC = f"{PATH_TO_SCRIPTS_R2P2}post-process/"
PATH_TO_SIM_RESULTS = f"{PATH_TO_SCRIPTS_R2P2}coord/results/"
PATH_TO_TMP_PLOT = PATH_TO_POSTPROC + "tmp_plot/"
PATH_TO_QTS_COMPARE_PARENT_DIR = PATH_TO_TMP_PLOT + "qts_direct_comparison_graphs/"
PATH_TO_THRPT_VS_LATENCY = PATH_TO_TMP_PLOT + "thrpt_latency_graphs/"

SSIRD_PLOT_COLOUR = 'tab:orange'
XPASS_PLOT_COLOUR = 'tab:green'
DCTCP_PLOT_COLOUR = 'tab:blue'

def plot_achieved_gdpt_vs_latency(
    experiment_family, title_addendum, experiment_date,
    ssird_achieved_gdpt_gbps_list, xpass_achieved_gdpt_gbps_list, dctcp_achieved_gdpt_gbps_list,
    ssird_fct_s_list_list, xpass_fct_s_list_list, dctcp_fct_s_list_list,
    percentile,
    x_lim=None, y_lim=None
):

    print([len(fct_list) for fct_list in ssird_fct_s_list_list])
    print([len(fct_list) for fct_list in xpass_fct_s_list_list])
    print([len(fct_list) for fct_list in dctcp_fct_s_list_list])

    plt.figure(figsize=(10, 6))
    plt.xlabel(f'Acheived Goodput (Gbps)')
    plt.ylabel(f'Latency (us) ({percentile}-th percentile)')
    plt.title(f'Achieved Goodput vs Latency\n{experiment_family}{title_addendum}\n{experiment_date}')

    ssird_fct_s_90p = [np.percentile(np.array(fct_s_list), percentile) for fct_s_list in ssird_fct_s_list_list]
    xpass_fct_s_90p = [np.percentile(np.array(fct_s_list), percentile) for fct_s_list in xpass_fct_s_list_list]
    dctcp_fct_s_90p = [np.percentile(np.array(fct_s_list), percentile) for fct_s_list in dctcp_fct_s_list_list]

    ssird_fct_us = [x*1000*1000 for x in ssird_fct_s_90p]
    xpass_fct_us = [x*1000*1000 for x in xpass_fct_s_90p]
    dctcp_fct_us = [x*1000*1000 for x in dctcp_fct_s_90p]
    # ssird_fct_ms = ssird_fct_s_90p
    # xpass_fct_ms = xpass_fct_s_90p
    # dctcp_fct_ms = dctcp_fct_s_90p

    print(ssird_fct_s_90p)
    print(xpass_fct_s_90p)
    print(dctcp_fct_s_90p)

    plt.plot(ssird_achieved_gdpt_gbps_list, ssird_fct_us, label="SSIRD", linestyle='-', marker='^', color=SSIRD_PLOT_COLOUR, markersize=8, zorder=3)
    plt.plot(xpass_achieved_gdpt_gbps_list, xpass_fct_us, label="ExpressPass", linestyle='-', marker='s', color=XPASS_PLOT_COLOUR, markersize=7, zorder=2)
    plt.plot(dctcp_achieved_gdpt_gbps_list, dctcp_fct_us, label="DCTCP", linestyle='-', marker='o', color=DCTCP_PLOT_COLOUR, markersize=7, zorder=1)

    plt.legend()

    ax = plt.gca()
    ax.grid(True, which='both')

    if (x_lim is not None):
        ax.set_xlim(x_lim)
    if (y_lim is not None):
        ax.set_ylim(y_lim)


    Path(PATH_TO_THRPT_VS_LATENCY).mkdir(parents=True, exist_ok=True)
    filename = f"allproto_achieved_gdpt_vs_latency_{experiment_family}{title_addendum}_{experiment_date}.png"
    plt.savefig(f"{PATH_TO_THRPT_VS_LATENCY}{filename}")
    plt.close()


def plot_achieved_gdpt_vs_slowdown(
    graph_name,
    experiment_family, title_addendum, experiment_date,
    byteload_size_B, inter_byteload_interval_nanosec, rtt_s,
    ssird_achieved_gdpt_gbps_list, xpass_achieved_gdpt_gbps_list, dctcp_achieved_gdpt_gbps_list,
    ssird_flowsize_fct_s_pairs_list_list, xpass_flowsize_fct_s_pairs_list_list, dctcp_flowsize_fct_s_pairs_list_list,
    percentile,
    x_lim=None, y_lim=None
):

    print([len(list) for list in ssird_flowsize_fct_s_pairs_list_list])
    print([len(list) for list in xpass_flowsize_fct_s_pairs_list_list])
    print([len(list) for list in dctcp_flowsize_fct_s_pairs_list_list])

    assert(len(set([
        len(ssird_flowsize_fct_s_pairs_list_list),
        len(xpass_flowsize_fct_s_pairs_list_list),
        len(dctcp_flowsize_fct_s_pairs_list_list)
    ]))==1)
    num_experiments = len(ssird_flowsize_fct_s_pairs_list_list)

    # plt.figure(figsize=(10, 6))
    plt.figure(figsize=(8, 4))
    plt.tight_layout()
    plt.xlabel(f'Acheived Goodput (Gbps)')
    plt.ylabel(f'Slowdown ({percentile}-th percentile)')
    # plt.title(f'Achieved Goodput vs Slowdown\n{experiment_family}{title_addendum}\n{experiment_date}')
    plt.title(f'Slowdown vs Achieved Goodput\n{graph_name}')

    ssird_slowdown_list_list = [] 
    xpass_slowdown_list_list = []
    dctcp_slowdown_list_list = []
    for i in range(num_experiments):

        ssird_flowsize_fct_s_pairs_list = ssird_flowsize_fct_s_pairs_list_list[i]
        ssird_slowdown = dale_fe_plot_flow_latency_cdf.get_flow_size_slowdown(
            byteload_size_B=byteload_size_B,
            inter_byteload_interval_nanosec=inter_byteload_interval_nanosec,
            rtt_s=rtt_s,
            flowsize_fct_s_pairs_list=ssird_flowsize_fct_s_pairs_list
        )
        ssird_slowdown_list_list.append(ssird_slowdown)

        xpass_flowsize_fct_s_pairs_list = xpass_flowsize_fct_s_pairs_list_list[i]
        xpass_slowdown = dale_fe_plot_flow_latency_cdf.get_flow_size_slowdown(
            byteload_size_B=byteload_size_B,
            inter_byteload_interval_nanosec=inter_byteload_interval_nanosec,
            rtt_s=rtt_s,
            flowsize_fct_s_pairs_list=xpass_flowsize_fct_s_pairs_list
        )
        xpass_slowdown_list_list.append(xpass_slowdown)

        dctcp_flowsize_fct_s_pairs_list = dctcp_flowsize_fct_s_pairs_list_list[i]
        dctcp_slowdown = dale_fe_plot_flow_latency_cdf.get_flow_size_slowdown(
            byteload_size_B=byteload_size_B,
            inter_byteload_interval_nanosec=inter_byteload_interval_nanosec,
            rtt_s=rtt_s,
            flowsize_fct_s_pairs_list=dctcp_flowsize_fct_s_pairs_list
        )
        dctcp_slowdown_list_list.append(dctcp_slowdown)

    ssird_slowdown_90p = [np.percentile(np.array(slowdown_list), percentile) for slowdown_list in ssird_slowdown_list_list]
    xpass_slowdown_90p = [np.percentile(np.array(slowdown_list), percentile) for slowdown_list in xpass_slowdown_list_list]
    dctcp_slowdown_90p = [np.percentile(np.array(slowdown_list), percentile) for slowdown_list in dctcp_slowdown_list_list]

    ssird = np.array(ssird_slowdown_90p).astype(float).tolist() 
    xpass = np.array(xpass_slowdown_90p).astype(float).tolist() 
    dctcp = np.array(dctcp_slowdown_90p).astype(float).tolist()
    print(ssird)
    print(xpass)
    print(dctcp)

    xpass_vs_ssird = [float(xpass_slowdown/ssird_slowdown) for xpass_slowdown, ssird_slowdown in zip(xpass_slowdown_90p, ssird_slowdown_90p)]
    dctcp_vs_ssird = [float(dctcp_slowdown/ssird_slowdown) for dctcp_slowdown, ssird_slowdown in zip(dctcp_slowdown_90p, ssird_slowdown_90p)]
    print(f"xpass_vs_ssird={xpass_vs_ssird}")
    print(f"dctcp_vs_ssird={dctcp_vs_ssird}")

    plt.plot(ssird_achieved_gdpt_gbps_list, ssird_slowdown_90p, label="SSIRD", linestyle='-', marker='^', color=SSIRD_PLOT_COLOUR, markersize=8, zorder=3)
    plt.plot(xpass_achieved_gdpt_gbps_list, xpass_slowdown_90p, label="ExpressPass", linestyle='-', marker='s', color=XPASS_PLOT_COLOUR, markersize=7, zorder=2)
    plt.plot(dctcp_achieved_gdpt_gbps_list, dctcp_slowdown_90p, label="DCTCP", linestyle='-', marker='o', color=DCTCP_PLOT_COLOUR, markersize=7, zorder=1)

    plt.legend()

    ax = plt.gca()
    ax.grid(True, which='both')

    if (x_lim is not None):
        ax.set_xlim(x_lim)
    if (y_lim is not None):
        ax.set_ylim(y_lim)


    Path(PATH_TO_THRPT_VS_LATENCY).mkdir(parents=True, exist_ok=True)
    filename = f"allproto_achieved_gdpt_vs_latency_{experiment_family}{title_addendum}_{experiment_date}.png"
    plt.savefig(f"{PATH_TO_THRPT_VS_LATENCY}{filename}")
    plt.close()



